colossal_redwood.source:
export const envelope = [14, 110, 14];

export default function build(api) {
  var W = api.size[0];
  var H = api.size[1];
  var D = api.size[2];
  var TAU = 6.283185307179586;
  var voxels = new Array(W * H * D);

  var instanceIndex = api.instance.index;
  var instanceCount = api.instance.count;
  var random = function () {
    return api.random();
  };

  var v0 = random();
  var v1 = random();
  var v2 = random();
  var v3 = random();
  var v4 = random();
  var v5 = random();
  var v6 = random();
  var v7 = random();
  var v8 = random();
  var v9 = random();
  var v10 = random();
  var v11 = random();
  var v12 = random();
  var v13 = random();
  var v14 = random();
  var v15 = random();
  var v16 = random();
  var v17 = random();
  var v18 = random();
  var v19 = random();
  var v20 = random();
  var v21 = random();

  var phase = v0 * TAU + instanceIndex * 0.271 + instanceCount * 0.017;
  var flutePhase = v1 * TAU + instanceIndex * 0.49;
  var trunkTop = 86 + ((Math.floor(v2 * 9) + instanceIndex * 2) % 9);
  var topY = 101 + ((Math.floor(v3 * 7) + instanceIndex) % 7);

  var leanX = (v4 - 0.5) * 1.15 + ((instanceIndex % 5) - 2) * 0.06;
  var leanZ = (v5 - 0.5) * 1.15 + (((instanceIndex + 2) % 5) - 2) * 0.06;
  var bendX = (v6 - 0.5) * 0.72;
  var bendZ = (v7 - 0.5) * 0.72;
  var kinkX = (v20 - 0.5) * 0.42;
  var kinkZ = (v21 - 0.5) * 0.42;
  var girth = 0.98 + v8 * 0.08;

  var rootCount = 6 + ((Math.floor(v9 * 4) + instanceIndex) % 4);
  var branchCount = 7 + ((Math.floor(v10 * 4) + instanceIndex * 3) % 4);
  var crownMode = (Math.floor(v11 * 3) + instanceIndex) % 3;
  var hollowWanted = v12 > 0.30 || instanceIndex % 5 === 0;
  var hollowSide = (Math.floor(v13 * 4) + instanceIndex) % 4;
  var hollowMinY = 3 + Math.floor(v14 * 2);
  var hollowWidth = 3 + (v15 > 0.68 ? 1 : 0);
  var crownScale = 0.86 + v18 * 0.42;

  var terrain = new Array(W);
  for (var tx = 0; tx < W; tx++) {
    terrain[tx] = new Array(D);
    for (var tz = 0; tz < D; tz++) {
      terrain[tx][tz] = api.heightAt(tx, tz);
    }
  }

  var cavity = null;
  var opening = null;

  if (hollowWanted) {
    var minX;
    var maxX;
    var minZ;
    var maxZ;

    if (hollowSide === 0) {
      minX = 8;
      maxX = 10;
      minZ = 5;
      maxZ = minZ + hollowWidth - 1;
      opening = { axis: "x", coord: 11, minL: minZ, maxL: maxZ };
    } else if (hollowSide === 1) {
      minX = 3;
      maxX = 5;
      minZ = 5;
      maxZ = minZ + hollowWidth - 1;
      opening = { axis: "x", coord: 2, minL: minZ, maxL: maxZ };
    } else if (hollowSide === 2) {
      minX = 5;
      maxX = minX + hollowWidth - 1;
      minZ = 8;
      maxZ = 10;
      opening = { axis: "z", coord: 11, minL: minX, maxL: maxX };
    } else {
      minX = 5;
      maxX = minX + hollowWidth - 1;
      minZ = 3;
      maxZ = 5;
      opening = { axis: "z", coord: 2, minL: minX, maxL: maxX };
    }

    cavity = {
      minX: minX,
      maxX: maxX,
      minY: hollowMinY,
      maxY: hollowMinY + 3,
      minZ: minZ,
      maxZ: maxZ
    };

    var groundOK = true;
    for (var cx = cavity.minX; cx <= cavity.maxX; cx++) {
      for (var cz = cavity.minZ; cz <= cavity.maxZ; cz++) {
        if (Math.ceil(terrain[cx][cz]) > cavity.minY - 1) {
          groundOK = false;
        }
      }
    }

    if (opening.axis === "x") {
      for (var checkZ = opening.minL; checkZ <= opening.maxL; checkZ++) {
        if (Math.ceil(terrain[opening.coord][checkZ]) > cavity.minY - 1) {
          groundOK = false;
        }
      }
    } else {
      for (var checkX = opening.minL; checkX <= opening.maxL; checkX++) {
        if (Math.ceil(terrain[checkX][opening.coord]) > cavity.minY - 1) {
          groundOK = false;
        }
      }
    }

    if (!groundOK) {
      cavity = null;
      opening = null;
    }
  }

  function voidCell(x, y, z) {
    if (cavity === null) {
      return false;
    }

    if (
      x >= cavity.minX &&
      x <= cavity.maxX &&
      y >= cavity.minY &&
      y <= cavity.maxY &&
      z >= cavity.minZ &&
      z <= cavity.maxZ
    ) {
      return true;
    }

    if (opening !== null && y >= cavity.minY && y <= cavity.maxY) {
      if (
        opening.axis === "x" &&
        x === opening.coord &&
        z >= opening.minL &&
        z <= opening.maxL
      ) {
        return true;
      }

      if (
        opening.axis === "z" &&
        z === opening.coord &&
        x >= opening.minL &&
        x <= opening.maxL
      ) {
        return true;
      }
    }

    return false;
  }

  function voxelIndex(x, y, z) {
    return (y * D + z) * W + x;
  }

  function place(x, y, z, block) {
    var xx = Math.round(x);
    var yy = Math.round(y);
    var zz = Math.round(z);

    if (xx < 0 || xx >= W || yy < 0 || yy >= H || zz < 0 || zz >= D) {
      return;
    }

    if (voidCell(xx, yy, zz)) {
      return;
    }

    var id = voxelIndex(xx, yy, zz);
    if (voxels[id] === undefined) {
      voxels[id] = block;
    }
  }

  function paint(x, y, z, block) {
    var xx = Math.round(x);
    var yy = Math.round(y);
    var zz = Math.round(z);

    if (xx < 0 || xx >= W || yy < 0 || yy >= H || zz < 0 || zz >= D) {
      return;
    }

    if (voidCell(xx, yy, zz)) {
      return;
    }

    var id = voxelIndex(xx, yy, zz);
    if (
      voxels[id] !== undefined &&
      voxels[id].indexOf("leaves") === -1
    ) {
      voxels[id] = block;
    }
  }

  function groundBottom(x, z) {
    var g = Math.ceil(terrain[x][z]);
    if (!(g >= 0)) {
      return 0;
    }
    if (g >= H) {
      return H - 1;
    }
    return g;
  }

  var logX = "minecraft:spruce_log[axis=x]";
  var logY = "minecraft:spruce_log[axis=y]";
  var logZ = "minecraft:spruce_log[axis=z]";
  var woodY = "minecraft:spruce_wood[axis=y]";
  var scarLight = "minecraft:stripped_spruce_log[axis=y]";
  var scarDark = "minecraft:dark_oak_log[axis=y]";
  var leaves = "minecraft:spruce_leaves[distance=7,persistent=true]";

  function centerX(y) {
    var t = y / trunkTop;
    if (t < 0) {
      t = 0;
    }
    if (t > 1) {
      t = 1;
    }

    return (
      6.5 +
      leanX * t +
      bendX * Math.sin(phase + y * 0.081) * t +
      kinkX * Math.sin(phase * 0.31 + TAU * t * 1.25) * t * t
    );
  }

  function centerZ(y) {
    var t = y / trunkTop;
    if (t < 0) {
      t = 0;
    }
    if (t > 1) {
      t = 1;
    }

    return (
      6.5 +
      leanZ * t +
      bendZ * Math.cos(phase + y * 0.076) * t +
      kinkZ * Math.sin(phase * 0.27 + TAU * t * 1.18) * t * t
    );
  }

  function trunkRadius(y) {
    var wobble = 0.035 * Math.sin(flutePhase + y * 0.17);

    if (y <= 14) {
      return (4.6 - 0.08 * y + wobble) * girth;
    }

    var t = (y - 14) / (trunkTop - 14);
    return (3.48 - 1.94 * t + wobble) * girth;
  }

  function clampInt(value, low, high) {
    var n = Math.round(value);
    if (n < low) {
      return low;
    }
    if (n > high) {
      return high;
    }
    return n;
  }

  function putAxis(x, y, z, axis) {
    if (axis === "x") {
      place(x, y, z, logX);
    } else if (axis === "z") {
      place(x, y, z, logZ);
    } else {
      place(x, y, z, logY);
    }
  }

  function connectPoints(a, b, axis) {
    var x = a.x;
    var y = a.y;
    var z = a.z;

    while (x !== b.x || y !== b.y || z !== b.z) {
      if (x !== b.x) {
        x += x < b.x ? 1 : -1;
      } else if (z !== b.z) {
        z += z < b.z ? 1 : -1;
      } else {
        y += y < b.y ? 1 : -1;
      }
      putAxis(x, y, z, axis);
    }
  }

  function drawLimb(sx, sy, sz, angle, length, rise, curve, thick, localPhase) {
    var steps = Math.max(3, Math.ceil(length * 4));
    var axis = Math.abs(Math.cos(angle)) >= Math.abs(Math.sin(angle)) ? "x" : "z";
    var previous = null;

    for (var i = 0; i <= steps; i++) {
      var t = i / steps;
      var sideOffset = curve * Math.sin(Math.PI * t);
      var verticalWiggle =
        0.18 *
        Math.sin(Math.PI * t + localPhase) *
        Math.sin(Math.PI * t);

      var rawX =
        sx +
        Math.cos(angle) * length * t -
        Math.sin(angle) * sideOffset;
      var rawZ =
        sz +
        Math.sin(angle) * length * t +
        Math.cos(angle) * sideOffset;
      var rawY = sy + rise * length * t + verticalWiggle;

      var current = {
        x: clampInt(rawX, 1, W - 2),
        y: clampInt(rawY, 1, H - 2),
        z: clampInt(rawZ, 1, D - 2)
      };

      if (previous !== null) {
        connectPoints(previous, current, axis);
      }

      putAxis(current.x, current.y, current.z, axis);

      var tubeRadius =
        thick > 0 && i <= steps * 0.30
          ? Math.max(1, Math.round(thick))
          : 0;

      for (var dx = -tubeRadius; dx <= tubeRadius; dx++) {
        for (var dz = -tubeRadius; dz <= tubeRadius; dz++) {
          if (dx * dx + dz * dz <= tubeRadius * tubeRadius + 0.1) {
            putAxis(current.x + dx, current.y, current.z + dz, axis);
          }
        }
      }

      previous = current;
    }

    return previous;
  }

  var clusters = [];

  function addCluster(x, y, z, rx, ry, rz, wobble) {
    clusters.push([x, y, z, rx, ry, rz, wobble]);
  }

  function leafBall(cx, cy, cz, rx, ry, rz, wobble) {
    var minLX = Math.floor(cx - rx - 1);
    var maxLX = Math.ceil(cx + rx + 1);
    var minLY = Math.floor(cy - ry - 1);
    var maxLY = Math.ceil(cy + ry + 1);
    var minLZ = Math.floor(cz - rz - 1);
    var maxLZ = Math.ceil(cz + rz + 1);

    for (var ly = minLY; ly <= maxLY; ly++) {
      var dy = (ly - cy) / Math.max(0.2, ry);

      for (var lz = minLZ; lz <= maxLZ; lz++) {
        var dz = (lz - cz) / Math.max(0.2, rz);

        for (var lx = minLX; lx <= maxLX; lx++) {
          var dx = (lx - cx) / Math.max(0.2, rx);
          var edge =
            0.07 *
            Math.sin(wobble + lx * 1.7 + ly * 2.1 + lz * 1.3);

          if (dx * dx + dy * dy + dz * dz <= 1 + edge) {
            place(lx, ly, lz, leaves);
          }
        }
      }
    }
  }

  for (var y = 0; y <= trunkTop; y++) {
    var cx0 = centerX(y);
    var cz0 = centerZ(y);
    var radius = trunkRadius(y);
    var xmin = Math.max(0, Math.floor(cx0 - radius - 1));
    var xmax = Math.min(W - 1, Math.ceil(cx0 + radius + 1));
    var zmin = Math.max(0, Math.floor(cz0 - radius - 1));
    var zmax = Math.min(D - 1, Math.ceil(cz0 + radius + 1));

    for (var x = xmin; x <= xmax; x++) {
      for (var z = zmin; z <= zmax; z++) {
        var ddx = x - cx0;
        var ddz = z - cz0;
        var radial = Math.sqrt(ddx * ddx + ddz * ddz);
        var angle = Math.atan2(ddz, ddx);
        var groove = Math.cos(
          angle * 6 +
          flutePhase +
          0.12 * Math.sin(y * 0.11)
        );
        var boundary =
          radius +
          0.38 * Math.max(0, groove) -
          0.10 * Math.max(0, -groove);

        if (radial <= boundary) {
          var trunkBlock = logY;

          if (radial > radius - 0.65 && groove > 0.45) {
            trunkBlock = woodY;
          } else if (radial > radius - 0.50 && groove < -0.65) {
            trunkBlock = scarDark;
          }

          place(x, y, z, trunkBlock);
        }
      }
    }
  }

  var baseCX = centerX(0);
  var baseCZ = centerZ(0);

  for (var fx = 1; fx < W - 1; fx++) {
    for (var fz = 1; fz < D - 1; fz++) {
      var fdx = fx - baseCX;
      var fdz = fz - baseCZ;
      var footRadial = Math.sqrt(fdx * fdx + fdz * fdz);
      var footLimit =
        4.45 +
        0.24 * Math.max(0, Math.cos(Math.atan2(fdz, fdx) * 6 + flutePhase));

      if (footRadial <= footLimit) {
        var collarUpTo = groundBottom(fx, fz) + 1;
        if (collarUpTo < 1) {
          collarUpTo = 1;
        }
        if (collarUpTo >= H) {
          collarUpTo = H - 1;
        }

        for (var fy = 0; fy <= collarUpTo; fy++) {
          place(fx, fy, fz, woodY);
        }
      }
    }
  }

  var rootPhase = phase + v1 * TAU * 0.37;
  var damagedRoot =
    (Math.floor(random() * rootCount) + instanceIndex) % rootCount;

  for (var ri = 0; ri < rootCount; ri++) {
    var rootAngle =
      rootPhase +
      (ri * TAU) / rootCount +
      (random() - 0.5) * 0.22;
    var rootLength = 4.25 + random() * 1.25;
    var rootHeight = 7 + Math.floor(random() * 5);
    var rootWidth = 1.0 + random() * 0.6;
    var rootCurve = (random() - 0.5) * 0.8;

    if (ri === damagedRoot) {
      rootLength *= 0.62;
      rootHeight = Math.max(4, Math.floor(rootHeight * 0.65));
    }

    var rootSteps = Math.max(4, Math.ceil(rootLength * 2));
    var rootAxis =
      Math.abs(Math.cos(rootAngle)) >= Math.abs(Math.sin(rootAngle))
        ? "x"
        : "z";

    for (var rs = 0; rs <= rootSteps; rs++) {
      var rt = rs / rootSteps;
      var dist = rootLength * rt;
      var sideways = rootCurve * Math.sin(Math.PI * rt);

      var rootX =
        baseCX +
        Math.cos(rootAngle) * dist -
        Math.sin(rootAngle) * sideways;
      var rootZ =
        baseCZ +
        Math.sin(rootAngle) * dist +
        Math.cos(rootAngle) * sideways;

      var rootCenterX = Math.round(rootX);
      var rootCenterZ = Math.round(rootZ);
      var halfWidth = 0.38 + (1 - rt) * rootWidth;
      var lateralLimit = Math.ceil(halfWidth);

      var rootTop =
        rootHeight * (1 - Math.pow(rt, 0.72)) +
        1.0 +
        1.2 * (1 - rt);
      rootTop = Math.min(H - 1, Math.floor(rootTop));

      for (var lateral = -lateralLimit; lateral <= lateralLimit; lateral++) {
        if (Math.abs(lateral) <= halfWidth + 0.01) {
          var rx = Math.round(
            rootCenterX - Math.sin(rootAngle) * lateral
          );
          var rz = Math.round(
            rootCenterZ + Math.cos(rootAngle) * lateral
          );

          if (rx < 0 || rx >= W || rz < 0 || rz >= D) {
            continue;
          }

          var bottom = groundBottom(rx, rz);
          for (var ry = bottom; ry <= rootTop; ry++) {
            putAxis(rx, ry, rz, rootAxis);
          }
        }
      }
    }
  }

  var scarCount =
    1 + ((Math.floor(random() * 3) + instanceIndex) % 3);
  var scarStartRange = Math.max(10, trunkTop - 38);

  for (var si = 0; si < scarCount; si++) {
    var scarStart = 16 + Math.floor(random() * scarStartRange);
    var scarEnd = Math.min(
      trunkTop - 5,
      scarStart + 5 + Math.floor(random() * 10)
    );
    if (scarEnd < scarStart) {
      scarEnd = scarStart;
    }

    var scarAngle = phase + random() * TAU;
    var scarWidth = 1 + Math.floor(random() * 2);
    var scarBlock =
      (si + instanceIndex) % 4 === 0 ? scarDark : scarLight;

    for (var sy = scarStart; sy <= scarEnd; sy++) {
      for (var slat = -scarWidth; slat <= scarWidth; slat++) {
        var irregular =
          Math.sin(sy * 1.17 + slat * 2.7 + scarAngle * 3.0);

        if (irregular <= -0.72) {
          continue;
        }

        var tangent =
          (slat + 0.18 * Math.sin(sy * 0.6 + si)) * 0.55;

        for (var depth = 0; depth < 5; depth++) {
          var scarRadius = trunkRadius(sy) - 0.05 - depth * 0.52;
          if (scarRadius < 0) {
            continue;
          }

          var sx = Math.round(
            centerX(sy) +
            Math.cos(scarAngle) * scarRadius -
            Math.sin(scarAngle) * tangent
          );
          var sz = Math.round(
            centerZ(sy) +
            Math.sin(scarAngle) * scarRadius +
            Math.cos(scarAngle) * tangent
          );

          if (sx < 0 || sx >= W || sz < 0 || sz >= D) {
            continue;
          }

          var scarId = voxelIndex(sx, sy, sz);
          if (
            voxels[scarId] !== undefined &&
            voxels[scarId].indexOf("leaves") === -1
          ) {
            paint(sx, sy, sz, scarBlock);
            break;
          }
        }
      }
    }
  }

  var leaderStart = trunkTop - 1;
  var leaderStartX = centerX(leaderStart);
  var leaderStartZ = centerZ(leaderStart);
  var leaderEndX = centerX(topY) + (v16 - 0.5) * 1.1;
  var leaderEndZ = centerZ(topY) + (v17 - 0.5) * 1.1;

  function leaderPoint(y) {
    var denom = topY - leaderStart;
    var t = denom === 0 ? 1 : (y - leaderStart) / denom;

    return {
      x: clampInt(
        leaderStartX + (leaderEndX - leaderStartX) * t,
        1,
        W - 2
      ),
      y: Math.round(y),
      z: clampInt(
        leaderStartZ + (leaderEndZ - leaderStartZ) * t,
        1,
        D - 2
      )
    };
  }

  var previousLeader = null;

  for (var ly = leaderStart; ly <= topY; ly++) {
    var lp = leaderPoint(ly);

    if (previousLeader !== null) {
      connectPoints(previousLeader, lp, "y");
    }

    putAxis(lp.x, lp.y, lp.z, "y");

    if (ly <= leaderStart + 2) {
      for (var ldx = -1; ldx <= 1; ldx++) {
        for (var ldz = -1; ldz <= 1; ldz++) {
          if (ldx * ldx + ldz * ldz <= 1) {
            putAxis(lp.x + ldx, lp.y, lp.z + ldz, "y");
          }
        }
      }
    }

    previousLeader = lp;
  }

  var leaderEnd = previousLeader;
  var bareBranch =
    (Math.floor(random() * branchCount) + instanceIndex) % branchCount;
  var branchPhase = phase + v1 * 0.73;
  var branchSpan = Math.max(12, trunkTop - 64);

  for (var bi = 0; bi < branchCount; bi++) {
    var fraction = bi / (branchCount - 1);
    var rawLevel =
      59 +
      Math.round(fraction * branchSpan) +
      Math.floor((random() - 0.5) * 4);
    var branchLevel = Math.max(
      58,
      Math.min(trunkTop - 4, rawLevel)
    );

    var branchAngle =
      branchPhase +
      (bi * TAU) / branchCount +
      (random() - 0.5) * 0.55;
    var branchLength =
      3.15 +
      random() * 1.65 +
      (bi % 3 === 0 ? 0.3 : 0);
    var branchRise = 0.16 + random() * 0.4;
    var branchCurve = (random() - 0.5) * 1.5;
    var branchStartX = centerX(branchLevel);
    var branchStartZ = centerZ(branchLevel);

    var branchEnd = drawLimb(
      branchStartX,
      branchLevel,
      branchStartZ,
      branchAngle,
      branchLength,
      branchRise,
      branchCurve,
      1,
      branchPhase + bi * 0.37
    );

    var endpointRadius = 1.35 + random() * 0.75;
    var endpointHeight = 1.2 + random() * 0.75;
    var endpointDepth =
      endpointRadius * (0.78 + random() * 0.22);

    if (bi !== bareBranch) {
      addCluster(
        branchEnd.x,
        branchEnd.y,
        branchEnd.z,
        endpointRadius,
        endpointHeight,
        endpointDepth,
        phase + bi * 1.7
      );
    } else if ((bi + instanceIndex) % 3 === 0) {
      addCluster(
        branchEnd.x,
        branchEnd.y,
        branchEnd.z,
        0.85,
        0.85,
        0.8,
        phase + bi * 1.7
      );
    }

    var midT = 0.54;
    var midSide = branchCurve * Math.sin(Math.PI * midT);
    var midpoint = {
      x: clampInt(
        branchStartX +
          Math.cos(branchAngle) * branchLength * midT -
          Math.sin(branchAngle) * midSide,
        1,
        W - 2
      ),
      y: clampInt(
        branchLevel + branchRise * branchLength * midT,
        1,
        H - 2
      ),
      z: clampInt(
        branchStartZ +
          Math.sin(branchAngle) * branchLength * midT +
          Math.cos(branchAngle) * midSide,
        1,
        D - 2
      )
    };

    if ((bi + instanceIndex) % 2 === 0 || bi === bareBranch) {
      var forkAngle =
        branchAngle +
        (bi % 2 === 0 ? 1 : -1) *
          (0.55 + random() * 0.35);
      var forkLength = 1.15 + random() * 1.3;
      var forkRise = 0.2 + random() * 0.4;
      var forkCurve = (random() - 0.5) * 0.8;

      var forkEnd = drawLimb(
        midpoint.x,
        midpoint.y,
        midpoint.z,
        forkAngle,
        forkLength,
        forkRise,
        forkCurve,
        1,
        phase + bi * 0.41
      );

      var forkRadius = 1.05 + random() * 0.5;
      if (bi !== bareBranch || (bi + instanceIndex) % 3 !== 1) {
        addCluster(
          forkEnd.x,
          forkEnd.y,
          forkEnd.z,
          forkRadius,
          1.0 + random() * 0.55,
          forkRadius * 0.9,
          phase + bi * 2.1
        );
      }
    }

    var twigCount = 1 + Math.floor(random() * 2);
    for (var ti = 0; ti < twigCount; ti++) {
      var twigAngle =
        branchAngle +
        (ti === 0 ? -1 : 1) *
          (0.45 + random() * 0.4) +
        (random() - 0.5) * 0.2;
      var twigLength = 1.15 + random() * 1.35;
      var twigRise = 0.22 + random() * 0.42;
      var twigCurve = (random() - 0.5) * 0.7;

      var twigEnd = drawLimb(
        branchEnd.x,
        branchEnd.y,
        branchEnd.z,
        twigAngle,
        twigLength,
        twigRise,
        twigCurve,
        0,
        phase + ti * 0.8 + bi
      );

      if (bi !== bareBranch || ti > 0) {
        var twigRadius = 1.0 + random() * 0.4;
        addCluster(
          twigEnd.x,
          twigEnd.y,
          twigEnd.z,
          twigRadius,
          0.95 + random() * 0.5,
          twigRadius * (0.8 + random() * 0.2),
          phase + ti * 1.4 + bi
        );
      }
    }
  }

  var crownMissing = Math.floor(random() * 4);

  if (crownMode === 0) {
    var coneBase = topY - 8;

    for (var layer = 0; layer <= 8; layer++) {
      var coneY = coneBase + layer;
      var conePoint = leaderPoint(coneY);
      var coneFraction = layer / 8;
      var coneRadius =
        3.05 * crownScale * (1 - coneFraction) + 0.72;
      var coneDepth =
        coneRadius *
        (0.80 + 0.10 * Math.sin(phase + layer));

      addCluster(
        conePoint.x,
        coneY,
        conePoint.z,
        coneRadius,
        1.12,
        coneDepth,
        phase + layer * 0.9
      );
    }
  } else if (crownMode === 1) {
    var umbrellaY = topY - 4;
    var umbrellaPoint = leaderPoint(umbrellaY);
    var umbrellaRadius = 3.1 * crownScale;

    addCluster(
      umbrellaPoint.x,
      umbrellaY,
      umbrellaPoint.z,
      umbrellaRadius,
      1.45,
      umbrellaRadius * 0.92,
      phase + 4.2
    );

    for (var uq = 0; uq < 4; uq++) {
      var umbrellaAngle =
        phase +
        uq * Math.PI * 0.5 +
        (random() - 0.5) * 0.3;
      var umbrellaLength = 2.0 + random() * 1.3;
      var umbrellaRise = 0.12 + random() * 0.28;
      var umbrellaCurve = (random() - 0.5) * 0.9;

      var umbrellaEnd = drawLimb(
        umbrellaPoint.x,
        umbrellaPoint.y,
        umbrellaPoint.z,
        umbrellaAngle,
        umbrellaLength,
        umbrellaRise,
        umbrellaCurve,
        1,
        phase + uq
      );

      if (uq !== crownMissing) {
        var umbrellaLeafRadius = 1.35 + random() * 0.7;
        addCluster(
          umbrellaEnd.x,
          umbrellaEnd.y,
          umbrellaEnd.z,
          umbrellaLeafRadius,
          1.1 + random() * 0.65,
          umbrellaLeafRadius * 0.9,
          phase + uq * 2.3
        );
      }
    }

    addCluster(
      leaderEnd.x,
      leaderEnd.y,
      leaderEnd.z,
      1.35 + v19 * 0.2,
      1.15,
      1.3,
      phase + 8.4
    );
  } else {
    var forkY = topY - 5;
    var forkPoint = leaderPoint(forkY);
    var crownForkCount =
      2 + ((instanceIndex + Math.floor(v19 * 2)) % 2);

    for (var fq = 0; fq < crownForkCount; fq++) {
      var crownForkAngle =
        phase +
        fq * (TAU / crownForkCount) +
        (random() - 0.5) * 0.35;
      var crownForkLength = 2.0 + random() * 1.25;
      var crownForkRise = 0.45 + random() * 0.35;
      var crownForkCurve = (random() - 0.5) * 0.75;

      var crownForkEnd = drawLimb(
        forkPoint.x,
        forkPoint.y,
        forkPoint.z,
        crownForkAngle,
        crownForkLength,
        crownForkRise,
        crownForkCurve,
        1,
        phase + fq * 0.7
      );

      if (fq !== crownMissing) {
        var crownForkRadius = 1.3 + random() * 0.7;
        addCluster(
          crownForkEnd.x,
          crownForkEnd.y,
          crownForkEnd.z,
          crownForkRadius,
          1.1 + random() * 0.6,
          crownForkRadius * 0.88,
          phase + fq * 2.6
        );
      }
    }

    for (var coneLayer = 0; coneLayer <= 4; coneLayer++) {
      var centralY = topY - 4 + coneLayer;
      var centralPoint = leaderPoint(centralY);
      var centralFraction = coneLayer / 4;
      var centralRadius =
        1.85 * crownScale * (1 - centralFraction) + 0.72;

      addCluster(
        centralPoint.x,
        centralY,
        centralPoint.z,
        centralRadius,
        1.12,
        centralRadius * 0.9,
        phase + 11 + coneLayer
      );
    }

    addCluster(
      leaderEnd.x,
      leaderEnd.y,
      leaderEnd.z,
      1.3 + v19 * 0.2,
      1.18,
      1.28,
      phase + 13.4
    );
  }

  for (var ci = 0; ci < clusters.length; ci++) {
    var cluster = clusters[ci];
    leafBall(
      cluster[0],
      cluster[1],
      cluster[2],
      cluster[3],
      cluster[4],
      cluster[5],
      cluster[6]
    );
  }

  for (var outY = 0; outY < H; outY++) {
    for (var outZ = 0; outZ < D; outZ++) {
      for (var outX = 0; outX < W; outX++) {
        var block = voxels[voxelIndex(outX, outY, outZ)];
        if (block !== undefined) {
          api.set(outX, outY, outZ, block);
        }
      }
    }
  }

  var baseAnchorX = clampInt(centerX(0), 0, W - 1);
  var baseAnchorZ = clampInt(centerZ(0), 0, D - 1);
  var anchors = {
    base: [baseAnchorX, 0, baseAnchorZ],
    crown: [leaderEnd.x, leaderEnd.y, leaderEnd.z]
  };

  if (cavity !== null && opening !== null) {
    var doorL = Math.floor((opening.minL + opening.maxL) * 0.5);

    if (opening.axis === "x") {
      anchors.door = [
        opening.coord,
        cavity.minY + 1,
        doorL
      ];
    } else {
      anchors.door = [
        doorL,
        cavity.minY + 1,
        opening.coord
      ];
    }
  }

  var result = {
    name: "Colossal Redwood",
    seatY: 0,
    anchors: anchors
  };

  if (cavity !== null) {
    result.interiors = [
      {
        min: [cavity.minX, cavity.minY, cavity.minZ],
        max: [cavity.maxX, cavity.maxY, cavity.maxZ],
        kind: "quarters"
      }
    ];
  }

  return result;
}
